func copyRandomList(head *Node) *Node {
    if head == nil {
        return nil
    }

    // 第一步：交织复制节点
    curr := head
    for curr != nil {
        copy := &Node{Val: curr.Val, Next: curr.Next}
        curr.Next = copy
        curr = copy.Next
    }

    // 第二步：设置 random 指针
    curr = head
    for curr != nil {
        if curr.Random != nil {
            curr.Next.Random = curr.Random.Next
        }
        curr = curr.Next.Next
    }

    // 第三步：拆分
    dummy := &Node{}
    copyCurr := dummy
    curr = head
    for curr != nil {
        copyCurr.Next = curr.Next
        copyCurr = copyCurr.Next
        curr.Next = curr.Next.Next
        curr = curr.Next
    }
    return dummy.Next
}

func copyRandomList(head *Node) *Node {
    if head == nil {
        return nil
    }
    m := make(map[*Node]*Node)
    curr := head
    for curr != nil {
        m[curr] = &Node{Val: curr.Val}
        curr = curr.Next
    }
    curr = head
    for curr != nil {
        m[curr].Next = m[curr.Next]
        m[curr].Random = m[curr.Random]
        curr = curr.Next
    }
    return m[head]
}
